def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and
                            (yy, xx) not in seen and grid[yy][xx] == color):
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            objects.append((color, cells))

    out = [[0] * w for _ in range(h)]
    # Drop each shape to the lowest available position; when blocked, it can
    # shift sideways to find a lower landing spot.
    objects.sort(key=lambda item: max(r for r, c in item[1]), reverse=True)
    for color, cells in objects:
        minc = min(c for r, c in cells)
        maxc = max(c for r, c in cells)
        best = None
        for left in range(w - (maxc - minc + 1) + 1):
            dc = left - minc
            for dr in range(h):
                placed = [(r + dr, c + dc) for r, c in cells]
                if any(y >= h for y, x in placed):
                    continue
                if any(out[y][x] for y, x in placed):
                    continue
                # ensure this is the lowest resting position for this shift
                if any(y + 1 < h and out[y + 1][x] == 0
                       for y, x in placed):
                    continue
                score = (max(y for y, x in placed), -abs(dc), -abs(dr))
                if best is None or score > best[0]:
                    best = (score, placed)
        if best is None:
            # fallback: place at original location if possible
            placed = cells
        else:
            placed = best[1]
        for y, x in placed:
            out[y][x] = color
    return out
